import React, { useState } from 'react'
import { useAuth } from '../context/AuthContext'
import axiosInstance from '../api/axiosInstance'

export function Login() {

    const [email, setEmail] = useState("")
    const [password, setPassword] = useState("")
    const { user, setUser } = useAuth()

    async function handleLogin(e) {
        e.preventDefault()
        const response = await axiosInstance.post('/player/login', { email, password })
        setUser(response.data)

    }
    return (
        <div>
            <h1>Login</h1>
            <form onSubmit={handleLogin}>
                <div><label >Email</label><input type="text" onChange={(e) => { setEmail(e.target.value) }} value={email} /></div>
                <div><label >Password</label><input type="password" onChange={(e) => { setPassword(e.target.value) }} value={password} /></div>
                <button >Login</button>
            </form>
        </div>
    )   
}
